const slides=[
{title:'The quote is sent. The next step is missing.',text:'A homeowner has a replacement estimate. Two weeks later, the quote is still open. Nobody knows whether they are comparing, waiting, or have a question.',bubble:'“We liked the quote. We just haven’t had time to talk it through.”'},
{title:'Start with eligible estimates.',text:'Read the agreed CRM fields. Exclude sold jobs, clear losses, active conversations, duplicates and opt-outs. Only contact homeowners through an appropriate approved channel.',bubble:'Example record: retail roof replacement · open estimate · follow-up due.'},
{title:'Make the follow-up specific.',text:'The message refers to the estimate the homeowner actually received. Approved information guides the reply. Pricing changes and uncertain answers go to the rep.',bubble:'“Hi Alex, it’s the estimate team at Example Roofing. Is there anything you still want to go through on the roof estimate?”'},
{title:'A reply becomes a useful sales handoff.',text:'The homeowner asks about timing. The system flags the question and creates a handoff for the roofing rep. The rep confirms details and arranges the estimate review.',bubble:'Rep brief: homeowner still considering · timing question · original estimate attached.'},
{title:'Track the result through to cash collected.',text:'Confirm that the review happened. Track any resulting sale separately. Track signed work and verified payments separately. A conversation or unsigned quote is not cash collected.',bubble:'Track: eligible → contacted → replied → review held → won / lost.'},
{title:'Check whether your pipeline fits.',text:'Bring your open-estimate count, average contribution per job, current CRM and current follow-up process. We’ll scope the pilot before any commitment.',bubble:'An eligible pipeline · a named sales rep · an agreed recovery target.'}];let n=0;const dialog=document.querySelector('#demo');function render(){let s=slides[n];document.querySelector('#slide').innerHTML=`<h2>${s.title}</h2><p>${s.text}</p><div class="demo-bubble">${s.bubble}</div>`;document.querySelector('#progress').textContent=`${n+1} / ${slides.length}`;document.querySelector('#prev').disabled=n===0;document.querySelector('#next').disabled=n===slides.length-1;}if(dialog && document.querySelector('#show-demo')){document.querySelector('#show-demo').onclick=()=>{n=0;render();dialog.showModal();};document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#prev').onclick=()=>{n--;render()};document.querySelector('#next').onclick=()=>{n++;render()};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
const questions=[{key:'type',title:'What type of roofing work do you mainly sell?',hint:'This programme is designed around residential replacement estimates.',options:['Residential retail roof replacements','Mostly insurance claims','Commercial roofing','Repairs / other']},{key:'volume',title:'How many unsold estimates have you sent in the last 90 days?',hint:'A rough count is fine. We’ll verify which ones are still worth pursuing.',options:['Under 100','100–199','200–399','400+','I’m not sure']},{key:'crm',title:'Where do you currently manage your estimates?',hint:'We start with your existing workflow.',options:['JobNimbus','AccuLynx','ServiceTitan','Other / spreadsheets']},{key:'rep',title:'Who would speak with homeowners who re-engage?',hint:'Your team handles the sales conversation and closes the job.',options:['A dedicated sales rep or team','Me—the business owner','Nobody is available yet']},{key:'company',title:'What’s your roofing company called?',type:'text',auto:'organization'},{key:'contact',title:'Where can we reach you?',hint:'Add your details below, then choose a time for your call.',fields:[{key:'name',label:'Full name',type:'text',auto:'name'},{key:'email',label:'Email address',type:'email',auto:'email'},{key:'phone',label:'Phone number',type:'tel',auto:'tel'}]}];let qi=0;const answers={};const qel=document.querySelector('#question');function showQ(){const q=questions[qi];document.querySelector('#qprogress').textContent=`Question ${qi+1} of ${questions.length}`;document.querySelector('#progress-fill').style.width=`${(qi+1)/questions.length*100}%`;qel.replaceChildren();const title=document.createElement('h3');title.textContent=q.title;qel.append(title);if(q.hint){const hint=document.createElement('p');hint.className='hint';hint.textContent=q.hint;qel.append(hint);}if(q.options){const box=document.createElement('div');box.className='choices';for(const [i,value] of q.options.entries()){const label=document.createElement('label');label.className='choice';const input=document.createElement('input');input.type='radio';input.name=q.key;input.value=value;input.checked=answers[q.key]===value;label.append(input,document.createTextNode(value));box.append(label);}qel.append(box);}else if(q.fields){const group=document.createElement('div');group.className='contact-fields';for(const f of q.fields){const label=document.createElement('label');label.className='field';label.textContent=f.label;const input=document.createElement('input');input.type=f.type;input.name=f.key;input.autocomplete=f.auto;input.required=true;input.value=answers[f.key]||'';if(f.type==='tel'){input.inputMode='tel';input.placeholder='Include country code';}label.append(input);group.append(label);}qel.append(group);}else{const label=document.createElement('label');label.className='field';const input=document.createElement('input');input.type=q.type;input.name=q.key;input.autocomplete=q.auto;input.value=answers[q.key]||'';input.setAttribute('aria-label',q.title);label.append(input);qel.append(label);}document.querySelector('#qback').disabled=qi===0;document.querySelector('#qnext').textContent=qi===questions.length-1?'See if I qualify →':'Continue →';document.querySelector('#qerror').textContent='';}function saveCurrent(){const q=questions[qi];const inputs=q.options?[qel.querySelector('input:checked')]:Array.from(qel.querySelectorAll('input'));for(const input of inputs){if(input)answers[input.name]=input.value.trim();}return inputs;}
document.querySelector('#qback').onclick=()=>{saveCurrent();if(qi>0){qi--;showQ();}};
document.querySelector('#fitform').onsubmit=e=>{e.preventDefault();const inputs=saveCurrent();const invalid=inputs.find(input=>!input||!input.value.trim()||!input.checkValidity()||(input.type==='tel'&&(input.value.replace(/\D/g,'').length<7||input.value.replace(/\D/g,'').length>15)));if(invalid!==undefined||inputs.some(i=>!i)){document.querySelector('#qerror').textContent=questions[qi].options?'Please choose one answer.':'Please complete each field with valid contact details.';invalid?.focus();return;}if(qi<questions.length-1){qi++;showQ();return;}// This preview qualifies applicants for a discovery call, not an implementation contract. No contact data is sent, persisted or added to the URL.
location.href='confirmation.html';};showQ();const sticky=document.querySelector('.sticky');new IntersectionObserver(([entry])=>{sticky.style.visibility=entry.isIntersecting?'hidden':'visible';},{threshold:0}).observe(document.querySelector('#apply'));
